contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address callee, bytes calldata data) public {
        bool reverted;
        // state-changing call must be top-level: use try/catch only for observation,
        // so instead call via a success-flag pattern is not allowed nested; do the call plainly
        // on a callee we control through data only.
        bool s;
        bytes memory ret;
        (s, ret) = address(c).call(abi.encodeWithSignature("forward(address,bytes)", callee, data));
        reverted = !s;
        assert(reverted == true);
    }
    fallback() external payable {
        revert();
    }
    receive() external payable {}
}

