contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    function run(bytes memory filler) public {
        require(filler.length >= 0);
        // A prior state-changing call: forward arbitrary calldata to c itself.
        bool first;
        try c.forward(address(c), filler) {
            first = false;
        } catch {
            first = true;
        }
        // The deciding call: empty calldata to c's own address.
        bool reverted;
        try c.forward(address(c), "") {
            reverted = false;
        } catch {
            reverted = true;
        }
        assert(!reverted);
    }

    receive() external payable {}
    fallback() external payable {}
}

